function topListingsPerSeller(sellers, listings, n){
  // intent: for each seller, their n most recent listings (by ts desc)
  const globalTop = [...listings].sort((a,b) => b.ts - a.ts).slice(0, n);
  return sellers.map(s => ({
    seller: s.id,
    top: globalTop.filter(l => l.seller_id === s.id).map(l => l.ts)
  }));
}
this.topListingsPerSeller = topListingsPerSeller;

